BEGIN;
CREATE TABLE public.compliance_licenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),source_key text,orgao text NOT NULL,documento text NOT NULL,numero text NOT NULL DEFAULT '',titular text NOT NULL DEFAULT '',emissao date,vencimento date,indeterminada boolean NOT NULL DEFAULT false,observacoes text NOT NULL DEFAULT '',version integer NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES auth.users(id),updated_by uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,source_key),CHECK(NOT indeterminada OR vencimento IS NULL),CHECK(emissao IS NULL OR vencimento IS NULL OR vencimento>=emissao));
CREATE INDEX compliance_license_due ON public.compliance_licenses(company_id,vencimento);CREATE INDEX compliance_license_creator ON public.compliance_licenses(created_by);CREATE INDEX compliance_license_updater ON public.compliance_licenses(updated_by);
CREATE TABLE public.compliance_change_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),entity_id uuid NOT NULL,entity text NOT NULL,action text NOT NULL,before_data jsonb,after_data jsonb,actor_id uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp());CREATE INDEX compliance_log_company ON public.compliance_change_log(company_id,created_at DESC);CREATE INDEX compliance_log_actor ON public.compliance_change_log(actor_id);
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['compliance_licenses','compliance_change_log'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t);EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t);EXECUTE format('CREATE POLICY company_read ON public.%I FOR SELECT TO authenticated USING(maintenance_private.partner_access(company_id))',t);END LOOP;END $$;
CREATE FUNCTION maintenance_private.compliance(c uuid,action text,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE l public.compliance_licenses;old_data jsonb;result jsonb;target uuid;field text;patch jsonb:='{}';current_data jsonb;BEGIN
IF auth.uid() IS NULL OR NOT maintenance_private.partner_access(c) THEN RAISE EXCEPTION 'Acesso não autorizado à empresa.' USING ERRCODE='42501';END IF;
IF action='list' THEN RETURN coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.vencimento NULLS LAST,x.documento) FROM public.compliance_licenses x WHERE company_id=c),'[]');END IF;
IF action='history' THEN RETURN coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM (SELECT * FROM public.compliance_change_log WHERE company_id=c AND entity_id=(b->>'id')::uuid ORDER BY created_at DESC LIMIT 100) x),'[]');END IF;
IF NOT maintenance_private.partner_access(c,true) THEN RAISE EXCEPTION 'Sem permissão para editar vencimentos.' USING ERRCODE='42501';END IF;
IF action='license_save' THEN
IF length(btrim(coalesce(b->>'orgao',''))) NOT BETWEEN 1 AND 160 OR length(btrim(coalesce(b->>'documento',''))) NOT BETWEEN 1 AND 240 OR length(coalesce(b->>'numero',''))>240 OR length(coalesce(b->>'titular',''))>240 OR length(coalesce(b->>'observacoes',''))>4000 THEN RAISE EXCEPTION 'Revise órgão, documento e demais campos.';END IF;
IF nullif(b->>'id','') IS NOT NULL THEN SELECT * INTO l FROM public.compliance_licenses WHERE id=(b->>'id')::uuid AND company_id=c FOR UPDATE;IF NOT FOUND OR l.version IS DISTINCT FROM (b->>'version')::integer THEN RAISE EXCEPTION 'Licença alterada. Recarregue antes de salvar.' USING ERRCODE='40001';END IF;old_data:=to_jsonb(l);
UPDATE public.compliance_licenses SET orgao=btrim(b->>'orgao'),documento=btrim(b->>'documento'),numero=btrim(coalesce(b->>'numero','')),titular=btrim(coalesce(b->>'titular','')),emissao=nullif(b->>'emissao','')::date,vencimento=CASE WHEN coalesce((b->>'indeterminada')::boolean,false) THEN NULL ELSE nullif(b->>'vencimento','')::date END,indeterminada=coalesce((b->>'indeterminada')::boolean,false),observacoes=btrim(coalesce(b->>'observacoes','')),version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() WHERE id=l.id RETURNING * INTO l;
ELSE INSERT INTO public.compliance_licenses(company_id,orgao,documento,numero,titular,emissao,vencimento,indeterminada,observacoes,created_by,updated_by) VALUES(c,btrim(b->>'orgao'),btrim(b->>'documento'),btrim(coalesce(b->>'numero','')),btrim(coalesce(b->>'titular','')),nullif(b->>'emissao','')::date,CASE WHEN coalesce((b->>'indeterminada')::boolean,false) THEN NULL ELSE nullif(b->>'vencimento','')::date END,coalesce((b->>'indeterminada')::boolean,false),btrim(coalesce(b->>'observacoes','')),auth.uid(),auth.uid()) RETURNING * INTO l;END IF;target:=l.id;result:=to_jsonb(l);
ELSIF action IN ('vehicle_dates','driver_dates') THEN
IF action='vehicle_dates' THEN SELECT to_jsonb(v) INTO current_data FROM public.veiculos v WHERE id=(b->>'id')::uuid AND company_id=c FOR UPDATE;
ELSE SELECT to_jsonb(d) INTO current_data FROM public.motoristas d WHERE id=(b->>'id')::uuid AND company_id=c FOR UPDATE;END IF;
IF current_data IS NULL THEN RAISE EXCEPTION 'Cadastro não encontrado na empresa.';END IF;
FOR field IN SELECT jsonb_object_keys(b->'dates') LOOP
IF NOT (field=ANY(CASE WHEN action='vehicle_dates' THEN ARRAY['validade_crlv','validade_cronotacografo','validade_cipp','validade_civ','validade_fumaca_opacidade','validade_seguro_ambiental'] ELSE ARRAY['validade_cnh','validade_toxicologico','validade_nr20','validade_nr35','validade_nr33','validade_direcao_defensiva','validade_cargas_especiais','validade_hazmat_pae'] END)) THEN RAISE EXCEPTION 'Campo de validade não autorizado.';END IF;
IF (current_data->field) IS DISTINCT FROM coalesce(b->'before'->field,'null'::jsonb) THEN RAISE EXCEPTION 'Validade alterada em outra tela. Atualize e tente novamente.' USING ERRCODE='40001';END IF;
IF nullif(b->'dates'->>field,'') IS NOT NULL THEN PERFORM (b->'dates'->>field)::date;END IF;
IF action='driver_dates' AND field='validade_cnh' AND nullif(b->'dates'->>field,'') IS NULL THEN RAISE EXCEPTION 'A validade da CNH não pode ficar vazia.';END IF;
patch:=patch||jsonb_build_object(field,nullif(b->'dates'->>field,''));
END LOOP;
IF patch='{}' THEN RAISE EXCEPTION 'Nenhuma validade informada.';END IF;
old_data:=current_data;target:=(b->>'id')::uuid;
FOR field IN SELECT jsonb_object_keys(patch) LOOP EXECUTE format('UPDATE public.%I SET %I=$1 WHERE id=$2 AND company_id=$3',CASE WHEN action='vehicle_dates' THEN 'veiculos' ELSE 'motoristas' END,field) USING (patch->>field)::date,target,c;END LOOP;
result:=current_data||patch;
ELSE RAISE EXCEPTION 'Ação inválida.';END IF;
INSERT INTO public.compliance_change_log(company_id,entity_id,entity,action,before_data,after_data,actor_id) VALUES(c,target,CASE WHEN action='license_save' THEN 'licenca' WHEN action='vehicle_dates' THEN 'veiculo' ELSE 'motorista' END,action,old_data,result,auth.uid());RETURN result;
END $$;
REVOKE ALL ON FUNCTION maintenance_private.compliance(uuid,text,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION maintenance_private.compliance(uuid,text,jsonb) TO authenticated;
CREATE FUNCTION public.compliance_command(target_company uuid,command text,body jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT maintenance_private.compliance(target_company,command,body);$$;
REVOKE ALL ON FUNCTION public.compliance_command(uuid,text,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.compliance_command(uuid,text,jsonb) TO authenticated;
DO $$ DECLARE def text;start_at integer;end_at integer;BEGIN
SELECT pg_get_functiondef('maintenance_private.order_effects()'::regprocedure) INTO def;start_at:=position('  IF EXISTS(SELECT 1 FROM public.maintenance_orders o WHERE o.company_id=NEW.company_id' in def);end_at:=position('  -- prepare_order' in def);IF start_at=0 OR end_at<=start_at THEN RAISE EXCEPTION 'Contrato de status da S.OR não encontrado';END IF;def:=substr(def,1,start_at-1)||'  -- A disponibilidade é alterada manualmente no cadastro da frota.'||chr(10)||substr(def,end_at);EXECUTE def;
END $$;
CREATE FUNCTION maintenance_private.manual_status_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
IF NEW.status IS DISTINCT FROM OLD.status AND auth.uid() IS NOT NULL THEN INSERT INTO public.compliance_change_log(company_id,entity_id,entity,action,before_data,after_data,actor_id) VALUES(NEW.company_id,NEW.id,CASE WHEN TG_TABLE_NAME='veiculos' THEN 'veiculo' ELSE 'motorista' END,'status_manual',jsonb_build_object('status',OLD.status),jsonb_build_object('status',NEW.status),auth.uid());END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION maintenance_private.manual_status_audit() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER audit_manual_availability AFTER UPDATE OF status ON public.veiculos FOR EACH ROW EXECUTE FUNCTION maintenance_private.manual_status_audit();
CREATE TRIGGER audit_manual_availability AFTER UPDATE OF status ON public.motoristas FOR EACH ROW EXECUTE FUNCTION maintenance_private.manual_status_audit();
COMMIT;
